import random
from typing import List, Dict, Optional

class QualityEvaluator:
    """Evaluates the quality of worker outputs based on skill and complexity."""
    
    def evaluate(self, output: str, subtask: Dict, worker_skill: float) -> Dict:
        """
        Evaluates a single worker output.
        
        Args:
            output: The text generated by the worker.
            subtask: Subtask definition dictionary.
            worker_skill: Skill level of the worker (0.0 - 1.0).
            
        Returns:
            Dictionary containing quality_score, failure_mode, passed, and feedback.
        """
        # Quality score formula
        base_score = worker_skill * (1 - subtask["complexity"] * 0.3)
        luck_factor = random.gauss(0, 0.1)  # stochastic noise
        final_score = max(0.0, min(1.0, base_score + luck_factor))
        
        failure_mode = None
        # Failure mode assignment
        if final_score < 0.3:
            # Hallucination (40%), off_task (30%), incomplete (30%)
            failure_mode = random.choices(
                ["hallucination", "off_task", "incomplete"],
                weights=[0.4, 0.3, 0.3],
                k=1
            )[0]
        elif 0.3 <= final_score < 0.6:
            # Incomplete (60%), None (40%)
            failure_mode = random.choices(
                ["incomplete", None],
                weights=[0.6, 0.4],
                k=1
            )[0]
        else:
            # No failure
            failure_mode = None
            
        passed = final_score >= 0.7
        
        feedback = f"Quality score: {final_score:.2f}. "
        if failure_mode:
            feedback += f"Detected failure mode: {failure_mode}. "
        else:
            feedback += "Output meets quality standards. "
            
        return {
            "quality_score": final_score,
            "failure_mode": failure_mode,
            "passed": passed,
            "feedback": feedback
        }

    def batch_evaluate(self, outputs: List[str], subtasks: List[Dict], worker_skills: List[float]) -> List[Dict]:
        """Evaluates a batch of worker outputs."""
        return [
            self.evaluate(out, sub, skill)
            for out, sub, skill in zip(outputs, subtasks, worker_skills)
        ]
